insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-ocurre-cuando-se-usa-material-de-otras-personas-sin-permiso','derecho',array['arte','sociedad']::text[],'¿Qué ocurre cuando se usa material de otras personas sin permiso?','Analiza qué consecuencias puede tener usar fotos, música, textos o código ajenos sin autorización, desde un aviso de retiro hasta sanciones, y cómo actuar de forma legal.','Análisis','~18 h',18,array['Infracción','Uso indebido']::text[],array['investigar']::text[],'publicos',NULL,'derecho comunicaciones educacion diseno ingenieria de sistemas sociologia administracion psicologia lectura de normas. analisis de casos. busqueda de recursos legales. redaccion clara. portales oficiales. un editor de documentos. bancos de recursos abiertos.',$a40sld${"id": "que-ocurre-cuando-se-usa-material-de-otras-personas-sin-permiso", "area": "derecho", "areas2": ["arte", "sociedad"], "titulo": "¿Qué ocurre cuando se usa material de otras personas sin permiso?", "resumen": "Analiza qué consecuencias puede tener usar fotos, música, textos o código ajenos sin autorización, desde un aviso de retiro hasta sanciones, y cómo actuar de forma legal.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Infracción", "Uso indebido"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Comunicaciones", "Educación", "Diseño", "Ingeniería de Sistemas", "Sociología", "Administración", "Psicología"], "problema": ["Copiar una imagen de internet, usar una canción de fondo en un video o pegar un texto sin citar parece algo menor, pero puede traer problemas: bajas de contenido, reclamos, multas o sanciones académicas.", "Conocer las consecuencias y las alternativas legales permite crear sin riesgos innecesarios."], "desarrollar": ["Con fuentes oficiales y casos públicos y anónimos, describe qué consecuencias pueden darse, como retiro de contenido, reclamos y sanciones, y cómo se procede cuando alguien denuncia.", "Redacta cinco casos inventados de uso sin permiso y para cada uno explica qué riesgo habría y qué alternativa legal tendría la persona, como pedir permiso, usar una licencia abierta o crear algo propio."], "ampliaciones": [{"titulo": "Cita legítima", "aporta": "explica cuándo se puede citar sin permiso y cómo hacerlo."}, {"titulo": "Plagio académico", "aporta": "compara el uso sin permiso con el plagio en trabajos."}, {"titulo": "Bancos de recursos libres", "aporta": "arma una lista de fuentes de material gratuito y legal."}], "objetivos": ["Conocer consecuencias de usos indebidos.", "Analizar casos.", "Proponer alternativas legales.", "Comunicar de forma sencilla."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Búsqueda de recursos legales.", "Redacción clara."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Bancos de recursos abiertos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no uses obras de otras personas como ejemplo sin citarlas."], "otroSector": "El mismo análisis sirve para el uso de datos, de marcas o de contenido generado por otras personas."}$a40sld$::jsonb,42),
('formas-de-proteger-una-creacion-original','derecho',array['negocios','arte']::text[],'Formas de proteger una creación original','Compara las formas de proteger una creación, como derecho de autor, marca, patente o secreto comercial, y ayuda a decidir cuál conviene según el tipo de creación.','Guía','~20 h',20,array['Protección','Creación']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho administracion diseno ingenieria de sistemas arquitectura economia ingenieria industrial comunicaciones analisis comparativo. lectura de normas. diseno de arboles de decision. comunicacion clara. portales oficiales. una tabla comparativa. un editor de diagramas.',$a41sld${"id": "formas-de-proteger-una-creacion-original", "area": "derecho", "areas2": ["negocios", "arte"], "titulo": "Formas de proteger una creación original", "resumen": "Compara las formas de proteger una creación, como derecho de autor, marca, patente o secreto comercial, y ayuda a decidir cuál conviene según el tipo de creación.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Protección", "Creación"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Diseño", "Ingeniería de Sistemas", "Arquitectura", "Economía", "Ingeniería Industrial", "Comunicaciones"], "problema": ["Una canción, un logo, un invento y un programa se protegen de maneras distintas. No siempre hace falta registrar, y en algunos casos conviene mantener un secreto.", "Saber cuál herramienta aplica a cada creación evita gastar dinero en trámites innecesarios o dejar sin protección algo valioso."], "desarrollar": ["Con fuentes oficiales, resume en una tabla cada forma de protección, qué protege, cómo se obtiene, cuánto dura y cuánto cuesta aproximadamente.", "Aplica la tabla a seis creaciones inventadas, como un logo, una app, una receta, un invento, una canción y un método de estudio, y recomienda qué protección conviene a cada una."], "ampliaciones": [{"titulo": "Ruta de decisión", "aporta": "dibuja un árbol que guíe al creador."}, {"titulo": "Costos y plazos", "aporta": "compara cuánto cuesta y cuánto demora cada trámite."}, {"titulo": "Protección en equipo", "aporta": "analiza qué conviene cuando varios crean algo juntos."}], "objetivos": ["Conocer formas de protección.", "Compararlas.", "Aplicarlas a casos.", "Recomendar con argumentos."], "habilidades": ["Análisis comparativo.", "Lectura de normas.", "Diseño de árboles de decisión.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Una tabla comparativa.", "Un editor de diagramas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "No presentes la guía como suficiente para proteger una invención real: consulta a un especialista antes de divulgarla."], "otroSector": "La misma comparación sirve para decidir cómo proteger un proyecto de investigación o un emprendimiento."}$a41sld$::jsonb,43),
('permisos-para-usar-imagenes-musica-o-textos-de-otras-personas-en','derecho',array['arte','educacion']::text[],'Permisos para usar imágenes, música o textos de otras personas en un proyecto','Arma un procedimiento claro para saber qué permisos se necesitan al usar imágenes, música o textos de otras personas en un trabajo académico, un video o una página web.','Guía','~18 h',18,array['Permisos','Uso de obras']::text[],array['resolver','crear']::text[],'publicos',NULL,'derecho comunicaciones diseno educacion ingenieria de sistemas arquitectura administracion psicologia diseno de procedimientos. lectura de normas. redaccion formal. pensamiento critico. un editor de diagramas. un editor de documentos. portales oficiales.',$a42sld${"id": "permisos-para-usar-imagenes-musica-o-textos-de-otras-personas-en", "area": "derecho", "areas2": ["arte", "educacion"], "titulo": "Permisos para usar imágenes, música o textos de otras personas en un proyecto", "resumen": "Arma un procedimiento claro para saber qué permisos se necesitan al usar imágenes, música o textos de otras personas en un trabajo académico, un video o una página web.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Permisos", "Uso de obras"], "intencion": ["resolver", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Comunicaciones", "Diseño", "Educación", "Ingeniería de Sistemas", "Arquitectura", "Administración", "Psicología"], "problema": ["Casi todo proyecto usa material ajeno: una imagen en una presentación, música en un video, un texto citado. Cada tipo exige condiciones distintas, y no siempre es evidente qué hacer.", "Un procedimiento sencillo evita errores y retiros de contenido."], "desarrollar": ["Diseña un árbol de decisión con preguntas como: ¿es una obra protegida?, ¿tiene licencia?, ¿es una cita?, ¿es para uso educativo?, ¿se publicará?, con la acción recomendada para cada caso.", "Aplícalo a ocho ejemplos de usos comunes, desde una imagen en un afiche hasta una canción en un video, y revisa con compañeros si las respuestas del árbol son claras."], "ampliaciones": [{"titulo": "Modelo de solicitud de permiso", "aporta": "redacta un correo para pedir permiso al autor."}, {"titulo": "Registro de fuentes", "aporta": "crea una hoja para llevar el control de lo que usas."}, {"titulo": "Alternativas", "aporta": "lista recursos libres para cada tipo de obra."}], "objetivos": ["Distinguir usos que requieren permiso.", "Diseñar un procedimiento claro.", "Aplicarlo a casos.", "Validarlo con usuarios."], "habilidades": ["Diseño de procedimientos.", "Lectura de normas.", "Redacción formal.", "Pensamiento crítico."], "herramientas": ["Un editor de diagramas.", "Un editor de documentos.", "Portales oficiales."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados y no uses obras de otras personas como ejemplo sin citarlas."], "otroSector": "El mismo procedimiento sirve para contenidos de un sitio web institucional, de una exposición o de un evento."}$a42sld$::jsonb,44),
('obras-protegidas-y-obras-de-uso-libre-como-distinguirlas','derecho',array['arte','educacion']::text[],'Obras protegidas y obras de uso libre: ¿cómo distinguirlas?','Aprende a reconocer si una obra está protegida, si es de dominio público o tiene licencia libre, y a buscar material que se pueda usar sin pedir permiso.','Guía','~16 h',16,array['Dominio público','Uso libre']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho diseno comunicaciones educacion ingenieria de sistemas arquitectura administracion psicologia lectura de normas. busqueda de recursos. verificacion de fuentes. organizacion de informacion. portales de recursos abiertos. un editor de documentos. hoja de calculo.',$a43sld${"id": "obras-protegidas-y-obras-de-uso-libre-como-distinguirlas", "area": "derecho", "areas2": ["arte", "educacion"], "titulo": "Obras protegidas y obras de uso libre: ¿cómo distinguirlas?", "resumen": "Aprende a reconocer si una obra está protegida, si es de dominio público o tiene licencia libre, y a buscar material que se pueda usar sin pedir permiso.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Dominio público", "Uso libre"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Diseño", "Comunicaciones", "Educación", "Ingeniería de Sistemas", "Arquitectura", "Administración", "Psicología"], "problema": ["No todo lo que está en internet es libre, pero tampoco todo está protegido: hay obras de dominio público, con licencias abiertas o hechas para compartirse. Distinguirlas no es obvio.", "Saber hacerlo permite usar buen material sin riesgos."], "desarrollar": ["Con fuentes oficiales, explica cuándo una obra pasa a dominio público, qué es una licencia abierta y cómo verificar el estado de una obra, con ejemplos.", "Elabora una lista de verificación para revisar una obra y busca cinco ejemplos de obras libres de distintos tipos, indicando cómo comprobaste su estado."], "ampliaciones": [{"titulo": "Buscadores de recursos libres", "aporta": "compara herramientas para buscar material abierto."}, {"titulo": "Dominio público en la práctica", "aporta": "estudia el caso de una obra clásica y sus adaptaciones."}, {"titulo": "Biblioteca de recursos", "aporta": "crea un banco organizado de recursos libres para tu carrera."}], "objetivos": ["Reconocer obras protegidas y libres.", "Verificar el estado de una obra.", "Buscar recursos legales.", "Organizar recursos."], "habilidades": ["Lectura de normas.", "Búsqueda de recursos.", "Verificación de fuentes.", "Organización de información."], "herramientas": ["Portales de recursos abiertos.", "Un editor de documentos.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad de derechos de autor.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Verifica siempre la fuente y las condiciones de cada obra antes de usarla."], "otroSector": "La misma guía sirve para trabajar con datos abiertos, documentos públicos o software libre."}$a43sld$::jsonb,45),
('como-funciona-una-institucion-publica-estructura-y-funciones','derecho',array['sociedad']::text[],'¿Cómo funciona una institución pública? Estructura y funciones','Elige una institución pública y explica cómo está organizada, qué funciones tiene, quién la dirige, cómo se financia y qué servicios ofrece, en una guía comprensible para cualquier persona.','Guía','~20 h',20,array['Instituciones','Estado']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho administracion sociologia comunicaciones economia educacion trabajo social lectura de documentos institucionales. sintesis. diseno de esquemas. comunicacion clara. portales institucionales. un editor de diagramas. un editor de documentos.',$a44sld${"id": "como-funciona-una-institucion-publica-estructura-y-funciones", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Cómo funciona una institución pública? Estructura y funciones", "resumen": "Elige una institución pública y explica cómo está organizada, qué funciones tiene, quién la dirige, cómo se financia y qué servicios ofrece, en una guía comprensible para cualquier persona.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Instituciones", "Estado"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Administración", "Sociología", "Comunicaciones", "Economía", "Educación", "Trabajo Social"], "problema": ["Las instituciones públicas están en la vida diaria, pero pocas personas saben cómo funcionan por dentro: qué áreas tienen, quién decide qué y de dónde sale su presupuesto.", "Entenderlo ayuda a saber a quién dirigirse y a participar con mejor criterio."], "desarrollar": ["Con fuentes oficiales, como la ley de creación, el organigrama y el portal institucional, describe la misión, la estructura, las principales funciones y los servicios de la institución elegida.", "Elabora un esquema visual de su organización, una guía de preguntas frecuentes y una lista de qué servicios puede esperar un ciudadano."], "ampliaciones": [{"titulo": "Presupuesto", "aporta": "añade de dónde recibe y cómo gasta sus recursos."}, {"titulo": "Línea de tiempo", "aporta": "explica cómo y cuándo se creó."}, {"titulo": "Comparar dos instituciones", "aporta": "compara dos instituciones con funciones parecidas."}], "objetivos": ["Identificar funciones y estructura.", "Usar fuentes oficiales.", "Representar visualmente una organización.", "Explicar con claridad."], "habilidades": ["Lectura de documentos institucionales.", "Síntesis.", "Diseño de esquemas.", "Comunicación clara."], "herramientas": ["Portales institucionales.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: describe funciones y procedimientos, sin opinar sobre personas, partidos o gestiones.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "No incluyas datos personales de funcionarios más allá de los cargos públicos."], "otroSector": "La misma guía sirve para entender cómo funciona una universidad, un hospital o una empresa grande."}$a44sld$::jsonb,46),
('servicios-que-ofrece-una-institucion-publica-a-los-ciudadanos','derecho',array['sociedad']::text[],'Servicios que ofrece una institución pública a los ciudadanos','Revisa qué servicios ofrece una institución pública a la ciudadanía, cómo se accede a cada uno, qué cuesta y qué tan fácil es encontrar esa información.','Análisis','~18 h',18,array['Servicios públicos','Ciudadanía']::text[],array['investigar']::text[],'publicos',NULL,'ciencias politicas administracion derecho trabajo social ingenieria de sistemas sociologia comunicaciones economia busqueda de informacion publica. evaluacion de usabilidad. clasificacion. propuestas de mejora. portales institucionales. hoja de calculo. un editor de directorios.',$a45sld${"id": "servicios-que-ofrece-una-institucion-publica-a-los-ciudadanos", "area": "derecho", "areas2": ["sociedad"], "titulo": "Servicios que ofrece una institución pública a los ciudadanos", "resumen": "Revisa qué servicios ofrece una institución pública a la ciudadanía, cómo se accede a cada uno, qué cuesta y qué tan fácil es encontrar esa información.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Servicios públicos", "Ciudadanía"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Administración", "Derecho", "Trabajo Social", "Ingeniería de Sistemas", "Sociología", "Comunicaciones", "Economía"], "problema": ["Muchas instituciones ofrecen servicios que la gente no conoce porque la información es difícil de encontrar o está redactada en lenguaje técnico. Así, se desaprovechan derechos y beneficios.", "Un inventario de servicios, con pasos de acceso, ayuda a que sean utilizados."], "desarrollar": ["Elige una institución, como una municipalidad o una oficina de empleo, y reúne con su portal los servicios que ofrece, requisitos, costos, plazos y canales de atención.", "Clasifica los servicios por tema y por facilidad de acceso, evalúa si la información es clara y propón cómo mejorar su presentación."], "ampliaciones": [{"titulo": "Directorio simple", "aporta": "crea un directorio fácil de usar de los servicios."}, {"titulo": "Prueba de usuario", "aporta": "pide a tres personas que encuentren un servicio y mide cuánto tardan."}, {"titulo": "Servicios que faltan", "aporta": "identifica servicios que la gente pide y no existen."}], "objetivos": ["Inventariar servicios públicos.", "Evaluar la claridad de la información.", "Clasificarlos.", "Proponer mejoras."], "habilidades": ["Búsqueda de información pública.", "Evaluación de usabilidad.", "Clasificación.", "Propuestas de mejora."], "herramientas": ["Portales institucionales.", "Hoja de cálculo.", "Un editor de directorios."], "lineamientos": ["Mantén una mirada neutral: describe funciones y procedimientos, sin opinar sobre personas, partidos o gestiones.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Presenta tus sugerencias como ideas de mejora."], "otroSector": "El mismo inventario sirve para servicios de una universidad, de una empresa o de un centro de salud."}$a45sld$::jsonb,47),
('comparando-el-rol-de-distintas-instituciones-en-un-mismo-tema','derecho',array['sociedad']::text[],'Comparando el rol de distintas instituciones en un mismo tema','Elige un tema, como el agua, la educación o el transporte, y descubre qué instituciones intervienen, qué hace cada una y cómo se coordinan.','Análisis','~22 h',22,array['Instituciones','Competencias']::text[],array['investigar']::text[],'publicos',NULL,'ciencias politicas derecho administracion sociologia economia ingenieria ambiental comunicaciones trabajo social analisis institucional. mapeo de actores. lectura de normas. comunicacion clara. un editor de diagramas. portales institucionales. hoja de calculo.',$a46sld${"id": "comparando-el-rol-de-distintas-instituciones-en-un-mismo-tema", "area": "derecho", "areas2": ["sociedad"], "titulo": "Comparando el rol de distintas instituciones en un mismo tema", "resumen": "Elige un tema, como el agua, la educación o el transporte, y descubre qué instituciones intervienen, qué hace cada una y cómo se coordinan.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Instituciones", "Competencias"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Administración", "Sociología", "Economía", "Ingeniería Ambiental", "Comunicaciones", "Trabajo Social"], "problema": ["Casi ningún tema público depende de una sola institución. El agua, por ejemplo, involucra a entidades que la regulan, la distribuyen, la fiscalizan y la planifican. Esa división de funciones confunde y a veces genera vacíos.", "Mapear quién hace qué en un tema permite entender el sistema y saber a quién pedir cuentas."], "desarrollar": ["Elige un tema público y con fuentes oficiales identifica las instituciones que intervienen, sus funciones, sus normas y cómo se relacionan.", "Dibuja un mapa institucional con flechas de coordinación, marca los puntos donde las funciones se superponen o faltan, y escribe una explicación para un lector sin conocimientos previos."], "ampliaciones": [{"titulo": "Un caso concreto", "aporta": "sigue un problema real y ve a cuántas instituciones involucra."}, {"titulo": "Comparar países", "aporta": "compara cómo se organiza el mismo tema en otro país."}, {"titulo": "Propuesta de coordinación", "aporta": "propón cómo mejorar la coordinación entre las instituciones."}], "objetivos": ["Identificar instituciones de un tema.", "Comparar funciones.", "Representar relaciones.", "Detectar superposiciones y vacíos."], "habilidades": ["Análisis institucional.", "Mapeo de actores.", "Lectura de normas.", "Comunicación clara."], "herramientas": ["Un editor de diagramas.", "Portales institucionales.", "Hoja de cálculo."], "lineamientos": ["Mantén una mirada neutral: describe funciones y procedimientos, sin opinar sobre personas, partidos o gestiones.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Describe sin atribuir culpas: tu análisis es del diseño institucional."], "otroSector": "El mismo mapeo sirve para temas dentro de una universidad o una empresa."}$a46sld$::jsonb,48),
('municipalidad-gobierno-regional-y-gobierno-nacional-que-hace-cad','derecho',array['ciudades','sociedad']::text[],'Municipalidad, gobierno regional y gobierno nacional: ¿qué hace cada uno?','Explica con ejemplos de la vida diaria las diferencias entre una municipalidad, un gobierno regional y el gobierno nacional, qué funciones tiene cada uno y a quién acudir en cada caso.','Guía','~20 h',20,array['Niveles de gobierno','Competencias']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho administracion sociologia geografia economia comunicaciones educacion lectura de normas de organizacion estatal. sintesis. diseno de materiales. comunicacion clara. portales oficiales. un editor de infografias. un editor de tarjetas.',$a47sld${"id": "municipalidad-gobierno-regional-y-gobierno-nacional-que-hace-cad", "area": "derecho", "areas2": ["ciudades", "sociedad"], "titulo": "Municipalidad, gobierno regional y gobierno nacional: ¿qué hace cada uno?", "resumen": "Explica con ejemplos de la vida diaria las diferencias entre una municipalidad, un gobierno regional y el gobierno nacional, qué funciones tiene cada uno y a quién acudir en cada caso.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Niveles de gobierno", "Competencias"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Administración", "Sociología", "Geografía", "Economía", "Comunicaciones", "Educación"], "problema": ["Cuando algo falla en la ciudad, la gente suele culpar al alcalde, al presidente o a quien aparece en las noticias, sin saber que cada nivel de gobierno tiene funciones distintas. Eso genera frustración y dificulta reclamar a quien corresponde.", "Una guía con ejemplos concretos ayuda a ubicar responsabilidades."], "desarrollar": ["Con las normas de organización del Estado, resume las funciones principales de cada nivel de gobierno y arma una tabla con ejemplos, como residuos, colegios, hospitales, carreteras y seguridad.", "Redacta diez situaciones cotidianas y para cada una indica qué nivel sería el principal responsable y a qué institución acudir, y valida las respuestas con un docente o con fuentes oficiales."], "ampliaciones": [{"titulo": "Juego de clasificación", "aporta": "crea tarjetas para que otros practiquen."}, {"titulo": "Presupuesto por nivel", "aporta": "explica de dónde recibe dinero cada nivel."}, {"titulo": "Un caso de tu distrito", "aporta": "analiza qué instituciones intervienen en un problema de tu zona."}], "objetivos": ["Distinguir niveles de gobierno.", "Asociar funciones con ejemplos.", "Identificar a quién acudir.", "Explicar con claridad."], "habilidades": ["Lectura de normas de organización estatal.", "Síntesis.", "Diseño de materiales.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Un editor de infografías.", "Un editor de tarjetas."], "lineamientos": ["Mantén una mirada neutral: describe funciones y procedimientos, sin opinar sobre personas, partidos o gestiones.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado."], "otroSector": "La misma guía sirve para explicar niveles de autoridad en una universidad o en una empresa."}$a47sld$::jsonb,49),
('como-se-aprueba-una-norma-en-el-peru-y-que-instituciones-partici','derecho',array['sociedad']::text[],'¿Cómo se aprueba una norma en el Perú y qué instituciones participan?','Explica con un diagrama cómo nace una ley o norma, desde la idea hasta su publicación, quién participa en cada etapa y en qué momentos la ciudadanía puede intervenir.','Guía','~22 h',22,array['Proceso legislativo','Normas']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ciencias politicas administracion sociologia comunicaciones educacion economia ingenieria de sistemas lectura de normas. diagramas de flujo. comunicacion clara. pensamiento civico. portales oficiales del congreso y del ejecutivo. un editor de diagramas. un editor de documentos.',$a48sld${"id": "como-se-aprueba-una-norma-en-el-peru-y-que-instituciones-partici", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Cómo se aprueba una norma en el Perú y qué instituciones participan?", "resumen": "Explica con un diagrama cómo nace una ley o norma, desde la idea hasta su publicación, quién participa en cada etapa y en qué momentos la ciudadanía puede intervenir.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Proceso legislativo", "Normas"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Sociología", "Comunicaciones", "Educación", "Economía", "Ingeniería de Sistemas"], "problema": ["Se habla de leyes y decretos como si aparecieran de la nada, pero tienen un recorrido con propuestas, debates, votaciones, observaciones y publicación. Casi nadie lo conoce, aunque las normas afectan la vida de todos.", "Entender el proceso ayuda a seguir los debates y a saber cuándo se puede participar."], "desarrollar": ["Con fuentes oficiales, describe las etapas por las que pasa una ley en el Perú, desde la iniciativa hasta la promulgación y publicación, y las instituciones que intervienen.", "Dibuja un diagrama de flujo, añade un ejemplo reciente de una norma, sin opinar sobre su contenido, y explica en qué momentos un ciudadano puede enterarse, opinar o proponer."], "ampliaciones": [{"titulo": "Diferentes normas", "aporta": "compara el proceso de una ley con el de una ordenanza."}, {"titulo": "Tiempo del proceso", "aporta": "estima cuánto tarda una ley en general."}, {"titulo": "Seguimiento", "aporta": "enseña cómo seguir un proyecto de ley en los portales oficiales."}], "objetivos": ["Conocer el proceso de aprobación de normas.", "Representarlo en un diagrama.", "Identificar instituciones.", "Ubicar momentos de participación."], "habilidades": ["Lectura de normas.", "Diagramas de flujo.", "Comunicación clara.", "Pensamiento cívico."], "herramientas": ["Portales oficiales del Congreso y del Ejecutivo.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: describe funciones y procedimientos, sin opinar sobre personas, partidos o gestiones.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Usa ejemplos de normas con fines didácticos, sin evaluar su conveniencia política."], "otroSector": "El mismo diagrama sirve para explicar cómo se aprueba un reglamento en una universidad o una decisión en una empresa."}$a48sld$::jsonb,50),
('ley-decreto-supremo-resolucion-y-ordenanza-que-diferencia-hay','derecho',array['sociedad','educacion']::text[],'Ley, decreto supremo, resolución y ordenanza: ¿qué diferencia hay?','Explica con ejemplos qué es cada tipo de norma, quién la emite, para qué sirve y qué jerarquía tiene, para que cualquier persona entienda cuándo algo es obligatorio y para quién.','Guía','~16 h',16,array['Jerarquía normativa','Normas']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ciencias politicas administracion comunicaciones educacion sociologia ingenieria de sistemas contabilidad lectura de normas. sintesis. diseno de materiales. comunicacion clara. portales oficiales de normas. un editor de infografias. un editor de tablas.',$a49sld${"id": "ley-decreto-supremo-resolucion-y-ordenanza-que-diferencia-hay", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "Ley, decreto supremo, resolución y ordenanza: ¿qué diferencia hay?", "resumen": "Explica con ejemplos qué es cada tipo de norma, quién la emite, para qué sirve y qué jerarquía tiene, para que cualquier persona entienda cuándo algo es obligatorio y para quién.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Jerarquía normativa", "Normas"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Comunicaciones", "Educación", "Sociología", "Ingeniería de Sistemas", "Contabilidad"], "problema": ["En las noticias se habla de leyes, decretos, resoluciones y ordenanzas como si fueran lo mismo, pero cada una tiene un autor, un alcance y una fuerza diferente. Confundirlas lleva a malentendidos sobre qué se debe cumplir.", "Distinguirlas es una base para entender cualquier trámite o debate público."], "desarrollar": ["Con fuentes oficiales, define cada tipo de norma, quién la emite, qué regula y cómo se jerarquiza, y arma una tabla y una pirámide visual.", "Busca un ejemplo real de cada tipo en portales oficiales, resume su contenido en dos líneas y explica a quién afecta y desde cuándo rige."], "ampliaciones": [{"titulo": "Cómo leer una norma", "aporta": "enseña a identificar número, fecha, objeto y artículos."}, {"titulo": "Quiz de clasificación", "aporta": "crea preguntas para que otros practiquen."}, {"titulo": "Normas de tu universidad", "aporta": "compara con la jerarquía de reglamentos internos."}], "objetivos": ["Distinguir tipos de normas.", "Comprender su jerarquía.", "Leer ejemplos reales.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Síntesis.", "Diseño de materiales.", "Comunicación clara."], "herramientas": ["Portales oficiales de normas.", "Un editor de infografías.", "Un editor de tablas."], "lineamientos": ["Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Usa normas con fines didácticos y sin opinar sobre su conveniencia."], "otroSector": "La misma guía sirve para entender la jerarquía de documentos en una organización, como estatutos, reglamentos y directivas."}$a49sld$::jsonb,51),
('como-consultar-si-una-norma-sigue-vigente-y-encontrar-su-version','derecho',array['tecnologia','sociedad']::text[],'Cómo consultar si una norma sigue vigente y encontrar su versión oficial','Enseña a verificar si una norma sigue vigente, si fue modificada o derogada, y dónde encontrar su texto oficial actualizado, en vez de fiarse de copias o resúmenes en internet.','Guía','~18 h',18,array['Vigencia','Fuentes oficiales']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ingenieria de sistemas administracion ciencias politicas comunicaciones contabilidad educacion sociologia busqueda en portales oficiales. verificacion de fuentes. pensamiento critico. redaccion clara. portales oficiales de normas. un editor de documentos. un editor de listas.',$a50sld${"id": "como-consultar-si-una-norma-sigue-vigente-y-encontrar-su-version", "area": "derecho", "areas2": ["tecnologia", "sociedad"], "titulo": "Cómo consultar si una norma sigue vigente y encontrar su versión oficial", "resumen": "Enseña a verificar si una norma sigue vigente, si fue modificada o derogada, y dónde encontrar su texto oficial actualizado, en vez de fiarse de copias o resúmenes en internet.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Vigencia", "Fuentes oficiales"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Administración", "Ciencias Políticas", "Comunicaciones", "Contabilidad", "Educación", "Sociología"], "problema": ["Es común compartir en redes imágenes o resúmenes de normas que ya cambiaron o nunca dijeron lo que se afirma. Usar información desactualizada lleva a errores, trámites rechazados o pagos innecesarios.", "Saber buscar la versión oficial y vigente es una habilidad básica para cualquier persona."], "desarrollar": ["Con portales oficiales, describe el paso a paso para encontrar una norma, verificar si fue modificada o derogada y distinguir el texto original del texto actualizado.", "Prueba el método con cinco normas, tres vigentes y dos modificadas, y elabora una lista de verificación y una guía de errores frecuentes."], "ampliaciones": [{"titulo": "Alertas", "aporta": "explica cómo seguir cambios en una norma."}, {"titulo": "Fuentes confiables", "aporta": "arma un listado de portales oficiales por tema."}, {"titulo": "Desinformación normativa", "aporta": "analiza un caso de información falsa sobre una norma, con fuentes."}], "objetivos": ["Buscar normas en fuentes oficiales.", "Verificar vigencia.", "Distinguir fuentes confiables.", "Elaborar una guía."], "habilidades": ["Búsqueda en portales oficiales.", "Verificación de fuentes.", "Pensamiento crítico.", "Redacción clara."], "herramientas": ["Portales oficiales de normas.", "Un editor de documentos.", "Un editor de listas."], "lineamientos": ["Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Evita compartir normas sin verificar su vigencia."], "otroSector": "El mismo método de verificación sirve para datos científicos, estadísticas oficiales o reglamentos internos."}$a50sld$::jsonb,52),
('recursos-para-explicar-normas-de-manera-sencilla','derecho',array['educacion','arte']::text[],'Recursos para explicar normas de manera sencilla','Toma una norma que afecte la vida diaria y conviértela en un recurso fácil de entender, como una infografía, un video corto o una lista de preguntas y respuestas.','Prototipo','~24 h',24,array['Lenguaje claro','Comunicación']::text[],array['crear']::text[],'publicos',NULL,'derecho comunicaciones diseno educacion ciencias politicas ingenieria de sistemas psicologia administracion lectura de normas. lenguaje claro. diseno de contenidos. pruebas de comprension. una norma oficial. un editor de infografias o de video. un formulario de opinion.',$a51sld${"id": "recursos-para-explicar-normas-de-manera-sencilla", "area": "derecho", "areas2": ["educacion", "arte"], "titulo": "Recursos para explicar normas de manera sencilla", "resumen": "Toma una norma que afecte la vida diaria y conviértela en un recurso fácil de entender, como una infografía, un video corto o una lista de preguntas y respuestas.", "tipo": "Prototipo", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Lenguaje claro", "Comunicación"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Comunicaciones", "Diseño", "Educación", "Ciencias Políticas", "Ingeniería de Sistemas", "Psicología", "Administración"], "problema": ["Las normas están escritas en un lenguaje técnico que aleja a la gente. Aunque deban cumplirse por todos, muchas personas no las entienden y dependen de rumores o de intermediarios.", "Traducir una norma a lenguaje claro, sin deformarla, es una forma de acercar la ciudadanía al derecho."], "desarrollar": ["Elige una norma breve de interés cotidiano, extrae sus ideas principales, identifica a quién afecta y qué obligaciones o derechos crea, y reescríbela con palabras sencillas.", "Crea un recurso, como una infografía o un video de un minuto, pruébalo con cinco personas que no conozcan la norma y mide si entienden lo esencial."], "ampliaciones": [{"titulo": "Lenguaje claro", "aporta": "aplica pautas de lenguaje claro y compara antes y después."}, {"titulo": "Versión en otro idioma", "aporta": "traduce a una lengua originaria o a otro idioma."}, {"titulo": "Pruebas de comprensión", "aporta": "diseña una prueba corta para medir si se entendió."}], "objetivos": ["Extraer ideas principales de una norma.", "Reescribir en lenguaje claro.", "Crear un recurso visual.", "Validarlo con usuarios."], "habilidades": ["Lectura de normas.", "Lenguaje claro.", "Diseño de contenidos.", "Pruebas de comprensión."], "herramientas": ["Una norma oficial.", "Un editor de infografías o de video.", "Un formulario de opinión."], "lineamientos": ["Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y las estructuras cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "No deformes el contenido: indica siempre cuál es el texto oficial y que tu recurso es una explicación."], "otroSector": "El mismo proceso sirve para explicar reglamentos universitarios, contratos o instrucciones técnicas."}$a51sld$::jsonb,53),
('como-participan-los-ciudadanos-en-los-asuntos-publicos-mecanismo','derecho',array['sociedad','educacion']::text[],'¿Cómo participan los ciudadanos en los asuntos públicos? Mecanismos para principiantes','Explica de forma sencilla qué maneras tiene una persona de participar en los asuntos públicos, como votar, proponer, consultar, vigilar o presentar iniciativas, y cuándo sirve cada una.','Guía','~22 h',22,array['Participación ciudadana','Mecanismos']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho sociologia trabajo social educacion comunicaciones administracion geografia lectura de normas de participacion. sintesis. diseno de materiales. pensamiento civico. portales oficiales. un editor de infografias. un editor de diagramas.',$a52sld${"id": "como-participan-los-ciudadanos-en-los-asuntos-publicos-mecanismo", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "¿Cómo participan los ciudadanos en los asuntos públicos? Mecanismos para principiantes", "resumen": "Explica de forma sencilla qué maneras tiene una persona de participar en los asuntos públicos, como votar, proponer, consultar, vigilar o presentar iniciativas, y cuándo sirve cada una.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Participación ciudadana", "Mecanismos"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Sociología", "Trabajo Social", "Educación", "Comunicaciones", "Administración", "Geografía"], "problema": ["Participar en lo público no se limita a votar. Existen mecanismos para opinar, proponer, vigilar y decidir, pero pocas personas los conocen y menos aún los usan.", "Una guía para principiantes puede mostrar el abanico de opciones y cómo empezar."], "desarrollar": ["Con fuentes oficiales, identifica los principales mecanismos de participación ciudadana vigentes, como presupuestos participativos, consultas, audiencias, cabildos o iniciativas, y explica cada uno con una definición, un ejemplo y un primer paso.", "Arma una guía visual con un cuadro comparativo y un diagrama de «¿qué mecanismo me conviene?» según lo que quiero lograr."], "ampliaciones": [{"titulo": "Nivel local, regional y nacional", "aporta": "organiza los mecanismos según el nivel de gobierno."}, {"titulo": "Ejemplos reales", "aporta": "añade un caso real de uso de cada mecanismo."}, {"titulo": "Quiz", "aporta": "crea preguntas para que otros prueben qué mecanismo conviene."}], "objetivos": ["Conocer mecanismos de participación.", "Compararlos.", "Diseñar una guía visual.", "Orientar a un lector principiante."], "habilidades": ["Lectura de normas de participación.", "Síntesis.", "Diseño de materiales.", "Pensamiento cívico."], "herramientas": ["Portales oficiales.", "Un editor de infografías.", "Un editor de diagramas."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado."], "otroSector": "La misma guía sirve para participación dentro de una universidad, un colegio o una organización."}$a52sld$::jsonb,54)
